<?php
namespace App\Filament\Resources\Promotions;
use App\Enums\UserRole; use App\Filament\Resources\Promotions\Pages\CreatePromotion; use App\Filament\Resources\Promotions\Pages\EditPromotion; use App\Filament\Resources\Promotions\Pages\ListPromotions; use App\Models\Promotion; use BackedEnum; use Filament\Actions\EditAction; use Filament\Forms\Components\DateTimePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Toggle; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\IconColumn; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table; use UnitEnum;
class PromotionResource extends Resource { protected static ?string $model = Promotion::class; protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedTag; protected static string|UnitEnum|null $navigationGroup = 'Operations'; protected static ?string $navigationLabel = 'Aturan harga'; protected static ?int $navigationSort = 10; public static function canViewAny(): bool { return false; } public static function canAccess(): bool { return in_array(auth()->user()?->role,[UserRole::Admin,UserRole::Owner,UserRole::Manager],true); } public static function form(Schema $schema): Schema { return $schema->components([TextInput::make('name')->label('Nama promo')->required(),Select::make('product_id')->label('Produk')->relationship('product','name')->searchable()->preload()->helperText('Kosongkan untuk semua produk.'),Select::make('type')->label('Jenis')->options(['percentage'=>'Diskon persen','fixed'=>'Diskon nominal','fixed_price'=>'Harga khusus'])->required(),TextInput::make('value')->label('Nilai')->numeric()->prefix('Rp / %')->minValue(0)->required(),Select::make('member_tier')->label('Khusus level member')->options(['regular'=>'Regular','silver'=>'Silver','gold'=>'Gold','platinum'=>'Platinum'])->placeholder('Semua pelanggan'),DateTimePicker::make('starts_at')->label('Mulai'),DateTimePicker::make('ends_at')->label('Berakhir'),Toggle::make('is_active')->label('Aktif')->default(true)])->columns(2); } public static function table(Table $table): Table { return $table->columns([TextColumn::make('name')->searchable(),TextColumn::make('product.name')->label('Produk')->placeholder('Semua produk'),TextColumn::make('type')->label('Jenis')->badge(),TextColumn::make('value')->label('Nilai'),TextColumn::make('member_tier')->label('Level')->placeholder('Semua'),TextColumn::make('ends_at')->label('Berakhir')->dateTime('d M Y H:i'),IconColumn::make('is_active')->label('Aktif')->boolean()])->recordActions([EditAction::make()]); } public static function getPages(): array { return ['index'=>ListPromotions::route('/'),'create'=>CreatePromotion::route('/create'),'edit'=>EditPromotion::route('/{record}/edit')]; } }
